import{_ as o,o as e,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Lei Trabalhista Simbiótica","description":"","frontmatter":{},"headers":[],"relativePath":"pt/41-共生劳动法.md","filePath":"pt/41-共生劳动法.md","lastUpdated":null}'),t={name:"pt/41-共生劳动法.md"};function d(s,a,n,l,c,m){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="lei-trabalhista-simbiotica" tabindex="-1">Lei Trabalhista Simbiótica <a class="header-anchor" href="#lei-trabalhista-simbiotica" aria-label="Permalink to &quot;Lei Trabalhista Simbiótica&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>41</td></tr><tr><td>Módulo</td><td>Sistema Jurídico e Estrutura de Governança</td></tr><tr><td>Palavras-chave principais</td><td>Trabalho Simbiótico, Mais Trabalho Mais Ganho, Direitos Trabalhistas, Contrato de Produção Conjunta, Anti-exploração</td></tr></tbody></table><h2 id="i-objetivo-legislativo-e-principios-fundamentais" tabindex="-1">I. Objetivo Legislativo e Princípios Fundamentais <a class="header-anchor" href="#i-objetivo-legislativo-e-principios-fundamentais" aria-label="Permalink to &quot;I. Objetivo Legislativo e Princípios Fundamentais&quot;">​</a></h2><p>A 《Lei Trabalhista Simbiótica》 é uma das leis centrais do sistema jurídico da civilização simbiótica de âncoras, paralela à 《Constituição Simbiótica》, visando regulamentar todas as atividades de trabalho e contribuição dentro de Hengyuanzhou, estabelecer a ordem de distribuição de &quot;mais trabalho mais ganho, crescimento autônomo&quot;, e erradicar as bases da exploração predatória no nível jurídico.</p><p>Esta lei estabelece os seguintes princípios fundamentais:</p><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Princípio da Dignidade do Trabalho</td><td>Todo trabalho legal é protegido por lei, a dignidade pessoal do trabalhador não pode ser violada</td></tr><tr><td>Princípio do Mais Trabalho Mais Ganho</td><td>A remuneração do trabalho está diretamente ligada à quantidade de contribuição, quanto maior a contribuição, maior o ganho, proibido o ganho sem trabalho</td></tr><tr><td>Princípio do Trabalho Voluntário</td><td>Proibido o trabalho forçado e a escravidão, o trabalhador tem o direito de escolher livremente o conteúdo e a forma de trabalho</td></tr><tr><td>Princípio da Remuneração Justa</td><td>Igual remuneração por trabalho igual, proibida a discriminação salarial com base em raça, nível de cultivo, origem</td></tr><tr><td>Princípio da Segurança no Trabalho</td><td>O Estado e a civilização têm a obrigação de fornecer aos trabalhadores um ambiente de trabalho seguro e segurança social básica</td></tr><tr><td>Princípio da Cooperação Simbiótica</td><td>Incentivar a cooperação e ajuda mútua entre trabalhadores, opor-se à competição predatória e ao jogo de soma zero</td></tr></tbody></table><h2 id="ii-direitos-fundamentais-dos-trabalhadores" tabindex="-1">II. Direitos Fundamentais dos Trabalhadores <a class="header-anchor" href="#ii-direitos-fundamentais-dos-trabalhadores" aria-label="Permalink to &quot;II. Direitos Fundamentais dos Trabalhadores&quot;">​</a></h2><p>A Lei Trabalhista Simbiótica concede a todos os seres com capacidade de trabalho dentro de Hengyuanzhou os seguintes direitos:</p><ol><li><strong>Direito ao Emprego Igualitário</strong>: Nenhum ser é discriminado por raça, nível de cultivo, origem, gênero, etc., no processo de busca de emprego e contratação.</li><li><strong>Direito à Escolha Livre de Profissão</strong>: O trabalhador tem o direito de escolher profissão, cargo e local de trabalho de acordo com sua própria vontade e capacidade, e tem o direito de mudar de profissão de acordo com a lei.</li><li><strong>Direito à Remuneração Razoável</strong>: O trabalhador tem o direito de receber remuneração compatível com sua contribuição de trabalho, a remuneração não pode ser inferior ao padrão mínimo de garantia estabelecido pela civilização.</li><li><strong>Direito ao Descanso e Férias</strong>: O trabalhador tem o direito de receber arranjo razoável de horário de trabalho e férias regulares, proibida a extensão ilimitada do horário de trabalho.</li><li><strong>Direito à Segurança no Trabalho</strong>: O trabalhador tem o direito de trabalhar em ambiente seguro e saudável, o empregador deve fornecer condições de proteção trabalhista que atendam aos padrões.</li><li><strong>Direito à Formação Profissional</strong>: O trabalhador tem o direito de receber formação de habilidades profissionais e orientação de cultivo, o empregador e o Estado têm a obrigação de fornecer recursos de formação.</li><li><strong>Direito de Associação e Negociação</strong>: O trabalhador tem o direito de organizar ou ingressar em associações de trabalhadores de acordo com a lei, e tem o direito de defender seus próprios direitos por meio de negociação coletiva.</li><li><strong>Direito de Recurso e Reclamação</strong>: O trabalhador, quando seus direitos trabalhistas são violados, tem o direito de apresentar reclamação e litígio perante o órgão de arbitragem trabalhista e o Tribunal Simbiótico.</li></ol><h2 id="iii-legalizacao-do-mecanismo-de-contrato-de-producao-conjunta" tabindex="-1">III. Legalização do Mecanismo de Contrato de Produção Conjunta <a class="header-anchor" href="#iii-legalizacao-do-mecanismo-de-contrato-de-producao-conjunta" aria-label="Permalink to &quot;III. Legalização do Mecanismo de Contrato de Produção Conjunta&quot;">​</a></h2><p>O mecanismo de contrato de produção conjunta é o sistema central de distribuição de recursos da civilização simbiótica de âncoras, e a 《Lei Trabalhista Simbiótica》 o fixa em forma jurídica:</p><ul><li><strong>Sujeito do Contrato</strong>: Qualquer ser com capacidade de trabalho pode ser sujeito do contrato, tanto indivíduos quanto coletivos podem contratar.</li><li><strong>Conteúdo do Contrato</strong>: Inclui, mas não se limita a, desenvolvimento de recursos de cultivo, manutenção de planos, transmissão de conhecimento, pesquisa e desenvolvimento tecnológico, serviços públicos, etc.</li><li><strong>Prazo do Contrato</strong>: Determinado de acordo com a natureza do conteúdo do contrato, contratos de curto prazo são de um a três anos, contratos de longo prazo são de cinco a vinte anos, podendo ser renovados ao vencer.</li><li><strong>Distribuição de Ganhos</strong>: O ganho do contratante está diretamente ligado à sua produção, parte da produção é entregue ao acúmulo público, a parte restante pertence ao contratante.</li><li><strong>Mecanismo de Saída</strong>: O contratante tem o direito de sair do contrato após notificação prévia dentro de prazo razoável, não pode ser forçado a permanecer na relação contratual.</li><li><strong>Resolução de Disputas</strong>: Disputas contratuais são resolvidas prioritariamente por arbitragem trabalhista, quem não concordar com o resultado da arbitragem pode processar no Tribunal Simbiótico.</li></ul><h2 id="iv-protecao-trabalhista-especial" tabindex="-1">IV. Proteção Trabalhista Especial <a class="header-anchor" href="#iv-protecao-trabalhista-especial" aria-label="Permalink to &quot;IV. Proteção Trabalhista Especial&quot;">​</a></h2><p>Para atender às necessidades especiais de diferentes formas de vida dentro de Hengyuanzhou, esta lei estabelece um sistema de proteção trabalhista especial:</p><table tabindex="0"><thead><tr><th>Grupo Protegido</th><th>Medidas de Proteção Especial</th></tr></thead><tbody><tr><td>Cultivadores Iniciantes</td><td>Não podem ser designados para trabalhos de alto risco além de sua capacidade, devem ser equipados com orientação de mentor</td></tr><tr><td>Seres Femininos em Período de Gravidez e Parto</td><td>Têm direito a licença maternidade remunerada de não menos de seis meses, não podem ser designados para trabalhos de alta intensidade durante o período de amamentação</td></tr><tr><td>Seres com Deficiência e Feridos/Doentes</td><td>Têm direito a ajuste razoável de cargo de trabalho e garantia de ambiente de trabalho acessível</td></tr><tr><td>Trabalhadores de Outras Raças</td><td>O empregador deve respeitar as características fisiológicas e hábitos culturais de outras raças, fornecendo condições de trabalho adaptadas</td></tr><tr><td>Trabalhadores Idosos</td><td>Ao atingir certa idade, podem solicitar redução da intensidade do trabalho ou transferência para cargo de consultoria</td></tr></tbody></table><h2 id="v-responsabilidade-juridica-e-garantia-de-implementacao" tabindex="-1">V. Responsabilidade Jurídica e Garantia de Implementação <a class="header-anchor" href="#v-responsabilidade-juridica-e-garantia-de-implementacao" aria-label="Permalink to &quot;V. Responsabilidade Jurídica e Garantia de Implementação&quot;">​</a></h2><p>O empregador que violar as disposições desta lei assumirá as seguintes responsabilidades de acordo com a gravidade da infração:</p><ol><li>Pagar a remuneração devida ao trabalhador e indenização (a indenização é de uma a três vezes a remuneração devida).</li><li>Ser ordenado a corrigir dentro do prazo, se não corrigir dentro do prazo, será multado.</li><li>Em casos graves, ter a licença comercial revogada e os responsáveis relevantes proibidos de exercer funções de gestão por certo período.</li><li>Se constituir crime, ser responsabilizado criminalmente de acordo com a lei.</li></ol><p>O Estado estabelece um órgão de inspeção trabalhista, responsável por supervisionar e inspecionar o cumprimento da lei trabalhista pelos empregadores. As associações de trabalhadores têm o direito de participar da inspeção trabalhista e da negociação coletiva em nome dos trabalhadores.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A 《Lei Trabalhista Simbiótica》 é o veículo jurídico do conceito de &quot;mais trabalho mais ganho&quot; da civilização simbiótica de âncoras. Ela transformou o trabalho de objeto de exploração em direito respeitado, e a distribuição de apropriação predatória em retribuição baseada em contribuição, estabelecendo uma base sólida do sistema trabalhista para o progresso comum de todas as raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Princípios Gerais da Constituição Simbiótica)</li><li>06-多劳多得分配原理 (Princípio de Distribuição do Mais Trabalho Mais Ganho)</li><li>22-资源分配联产承包机制 (Mecanismo de Contrato de Produção Conjunta de Distribuição de Recursos)</li><li>42-消费者保护法 (Lei de Proteção ao Consumidor)</li></ul>',23)])])}const p=o(t,[["render",d]]);export{b as __pageData,p as default};
